import 'package:sequential_runner/sequential_runner.dart';

Future<void> main() async {
  final log = <String>[];
  final results = await SequentialRunner.runAll<int>([
    () async {
      log.add('start1');
      await Future<void>.delayed(const Duration(milliseconds: 100));
      log.add('end1');
      return 1;
    },
    () async {
      log.add('start2');
      await Future<void>.delayed(const Duration(milliseconds: 10));
      log.add('end2');
      return 2;
    },
    () async => 3,
  ]);
  print(log.join(','));
  print(results.join(','));
  if (log.join(',') != 'start1,end1,start2,end2') {
    throw StateError('NOT SEQUENTIAL');
  }
  if (results.join(',') != '1,2,3') {
    throw StateError('BAD ORDER');
  }
  print('OK');
}
EOF
dart run /tmp/seq_check.dart

